<#
  Jarvis overlay setup for Venus
  ------------------------------
  Run in a NORMAL (not admin) PowerShell window:

    powershell -NoProfile -ExecutionPolicy Bypass -File "$env:USERPROFILE\Downloads\jarvis-overlay-setup.ps1"

  What it does (per-user only, no admin, safe to re-run):
    1. Finds the ha-windows build with the event stream hook (the GitHub Actions artifact
       zip in Downloads) and checks its SHA-256 against the hash below.
    2. Stops ha-windows, keeps the stock exe as a backup, and swaps in the new build.
       The path doesn't change, so the firewall rules still apply.
    3. Turns off the built-in grey bubbles and adds --event-port 6054 to the ha-windows Startup shortcut.
    4. Installs the overlay to %LOCALAPPDATA%\Programs\JarvisOverlay and adds a Startup shortcut.
    5. Starts both and checks that the overlay is receiving events.

  Undo: run it again with -Uninstall.
#>
[CmdletBinding()]
param(
    [string]$PatchedExe,
    [switch]$Uninstall,
    [switch]$Demo
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

# ---------------- settings (filled in when this file was generated) ----------------
$Port           = 6054
$ExpectedSha256 = 'f7ab234db3d0962f87ce79b609d7a0f649774f134c9f6bf56c1ee567273b2af3'
$BuildLabel     = 'ha-windows 1.4.3 + event stream (moorew/ha-windows@59c861d, CI run 39310942170)'
$ArtifactUrl    = 'https://github.com/moorew/ha-windows/actions/runs/39310942170'
$OverlayB64     = ''

$HawDir      = Join-Path $env:LOCALAPPDATA 'Programs\HomeAssistantWindows'
$HawExe      = Join-Path $HawDir 'HomeAssistantWindows.exe'
$HawBackup   = Join-Path $HawDir 'HomeAssistantWindows.stock.exe'
$HawData     = Join-Path $env:USERPROFILE 'AppData\Local\HomeAssistantWindows'
$HawPrefs    = Join-Path $HawData 'preferences.json'
$HawLog      = Join-Path $HawData 'ha_windows.log'
$OvDir       = Join-Path $env:LOCALAPPDATA 'Programs\JarvisOverlay'
$OvScript    = Join-Path $OvDir 'jarvis-overlay.ps1'
$OvLog       = Join-Path $env:LOCALAPPDATA 'JarvisOverlay\overlay.log'
$Startup     = [Environment]::GetFolderPath('Startup')
$HawLnk      = Join-Path $Startup 'Home Assistant Windows.lnk'
$OvLnk       = Join-Path $Startup 'Jarvis Overlay.lnk'
$Utf8NoBom   = New-Object Text.UTF8Encoding($false)

function Ok([string]$m)   { Write-Host "  [OK]   $m" -ForegroundColor Green }
function Warn([string]$m) { Write-Host "  [WARN] $m" -ForegroundColor Yellow }
function Fail([string]$m) { Write-Host "  [FAIL] $m" -ForegroundColor Red }
function Info([string]$m) { Write-Host "         $m" }
function Section([string]$t) { Write-Host ''; Write-Host "== $t ==" -ForegroundColor Cyan }
function Get-Sha256([string]$p) { (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant() }

function Set-Shortcut([string]$path, [string]$target, [string]$arguments, [string]$workDir, [string]$icon, [string]$description) {
    $ws = New-Object -ComObject WScript.Shell
    $sc = $ws.CreateShortcut($path)
    $sc.TargetPath = $target
    $sc.Arguments = $arguments
    $sc.WorkingDirectory = $workDir
    if ($icon) { $sc.IconLocation = $icon }
    $sc.Description = $description
    $sc.Save()
}

function Set-BubblePreference([bool]$enabled) {
    $data = [ordered]@{}
    if (Test-Path -LiteralPath $HawPrefs) {
        $obj = [IO.File]::ReadAllText($HawPrefs, $Utf8NoBom) | ConvertFrom-Json
        foreach ($p in $obj.PSObject.Properties) { $data[$p.Name] = $p.Value }
    }
    $data['conversation_bubble_enabled'] = $enabled
    New-Item -ItemType Directory -Path $HawData -Force | Out-Null
    # ha-windows reads this with Python's json module, which rejects a UTF-8 BOM
    [IO.File]::WriteAllText($HawPrefs, ($data | ConvertTo-Json -Depth 5), $Utf8NoBom)
}

function Stop-HaWindows {
    $procs = @(Get-Process -Name 'HomeAssistantWindows' -ErrorAction SilentlyContinue)
    if ($procs.Count -eq 0) { return $true }
    try {
        $procs | Stop-Process -Force -ErrorAction Stop
    } catch {
        Fail 'Could not stop ha-windows. It is probably running as administrator.'
        Info 'Quit it from the tray icon (right-click > Quit), then run this script again.'
        return $false
    }
    for ($i = 0; $i -lt 20 -and @(Get-Process -Name 'HomeAssistantWindows' -ErrorAction SilentlyContinue).Count -gt 0; $i++) { Start-Sleep -Milliseconds 500 }
    Start-Sleep -Seconds 1
    return $true
}

function Stop-Overlay {
    Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe'" -ErrorAction SilentlyContinue |
        Where-Object { $_.CommandLine -and $_.CommandLine -like '*jarvis-overlay.ps1*' -and $_.ProcessId -ne $PID } |
        ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
}

function Wait-Listen([int]$port, [int]$seconds) {
    $deadline = (Get-Date).AddSeconds($seconds)
    while ((Get-Date) -lt $deadline) {
        if (@(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue).Count -gt 0) { return $true }
        Start-Sleep -Seconds 1
    }
    return $false
}

# ---------------- refuse to run elevated ----------------
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if ($isAdmin -and $env:JARVIS_SETUP_ALLOW_ADMIN -ne '1') {   # the override exists only for the CI test run
    Fail 'This window is running as administrator.'
    Info 'Open a normal PowerShell window and run it there, so ha-windows and the overlay start without admin rights.'
    exit 1
}

# ---------------- uninstall ----------------
if ($Uninstall) {
    Section 'Undo'
    Stop-Overlay
    if (Test-Path -LiteralPath $OvLnk) { Remove-Item -LiteralPath $OvLnk -Force; Ok 'Removed the overlay Startup shortcut' }
    if (-not (Stop-HaWindows)) { exit 1 }
    if (Test-Path -LiteralPath $HawBackup) { Copy-Item -LiteralPath $HawBackup -Destination $HawExe -Force; Ok 'Restored the stock ha-windows exe' }
    Set-Shortcut $HawLnk $HawExe '' $HawDir "$HawExe,0" 'Home Assistant voice satellite (ha-windows)'
    Ok 'ha-windows Startup shortcut back to no arguments'
    Set-BubblePreference $true
    Ok 'Built-in bubbles turned back on'
    Start-Process -FilePath $HawLnk
    Ok 'Started ha-windows'
    Info "The overlay files are still in $OvDir if you want them later."
    exit 0
}

# =========================================================
Section '1. ha-windows build with the event stream'
Info "Build: $BuildLabel"
$src = $null
if ($PatchedExe) {
    $src = (Resolve-Path -LiteralPath $PatchedExe).Path
} else {
    $dl = Join-Path $env:USERPROFILE 'Downloads'
    $cand = @(Get-ChildItem -LiteralPath $dl -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like 'ha-assistant-windows-exe*.zip' -or ($_.Name -like 'HomeAssistantWindows*.exe' -and $_.Name -notlike '*Setup*') } |
        Sort-Object LastWriteTime -Descending)
    foreach ($c in $cand) { $src = $c.FullName; break }
}
if (-not $src) {
    Fail 'Could not find the build in Downloads.'
    Info "Download the 'ha-assistant-windows-exe' artifact from: $ArtifactUrl"
    Info 'Save the zip to Downloads (no need to unzip it), then run this script again.'
    exit 1
}
Info "Using: $src"

$tmp = Join-Path $env:TEMP ('jarvis-setup-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tmp -Force | Out-Null
try {
    $exe = $src
    if ($src -like '*.zip') {
        Expand-Archive -LiteralPath $src -DestinationPath $tmp -Force
        $exe = @(Get-ChildItem -LiteralPath $tmp -Recurse -File -Filter 'HomeAssistantWindows.exe')[0].FullName
        if (-not $exe) { throw "No HomeAssistantWindows.exe inside $src" }
    }
    $hash = Get-Sha256 $exe
    if ($hash -ne $ExpectedSha256) {
        Fail "SHA-256 mismatch. Got $hash, expected $ExpectedSha256. Nothing was changed."
        exit 1
    }
    Ok "SHA-256 verified: $hash"

    # =========================================================
    Section '2. Swap the exe'
    if ((Test-Path -LiteralPath $HawExe) -and ((Get-Sha256 $HawExe) -eq $ExpectedSha256)) {
        Ok 'Already installed'
        if (-not (Stop-HaWindows)) { exit 1 }
    } else {
        if (-not (Stop-HaWindows)) { exit 1 }
        if ((Test-Path -LiteralPath $HawExe) -and -not (Test-Path -LiteralPath $HawBackup)) {
            Copy-Item -LiteralPath $HawExe -Destination $HawBackup
            Ok "Stock exe kept as $HawBackup"
        }
        New-Item -ItemType Directory -Path $HawDir -Force | Out-Null
        Copy-Item -LiteralPath $exe -Destination $HawExe -Force
        Unblock-File -LiteralPath $HawExe -ErrorAction SilentlyContinue
        Ok "Installed the new build at $HawExe"
    }
} finally {
    Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
}

# =========================================================
Section '3. ha-windows settings'
Set-BubblePreference $false
Ok 'Built-in grey bubbles turned off (tray menu: Show Conversation Bubbles)'
Set-Shortcut $HawLnk $HawExe "--event-port $Port" $HawDir "$HawExe,0" 'Home Assistant voice satellite (ha-windows)'
Ok "Startup shortcut now starts ha-windows with --event-port $Port"

# =========================================================
Section '4. Overlay'
New-Item -ItemType Directory -Path $OvDir -Force | Out-Null
$overlayText = $Utf8NoBom.GetString([Convert]::FromBase64String($OverlayB64))
[IO.File]::WriteAllText($OvScript, $overlayText, (New-Object Text.UTF8Encoding($true)))
Ok "Overlay installed: $OvScript"
$ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
$conhost = Join-Path $env:SystemRoot 'System32\conhost.exe'
# conhost --headless runs PowerShell with no console window at all
Set-Shortcut $OvLnk $conhost "--headless `"$ps`" -NoProfile -ExecutionPolicy Bypass -File `"$OvScript`" -Port $Port" $OvDir "$ps,0" 'Jarvis overlay for ha-windows'
Ok "Startup shortcut: $OvLnk"

# =========================================================
Section '5. Start and check'
$logStart = 0
if (Test-Path -LiteralPath $HawLog) { $logStart = (Get-Item -LiteralPath $HawLog).Length }
Start-Process -FilePath $HawLnk
Info 'Started ha-windows. Waiting for it to come up (first start can take 30 s or more)...'
if (Wait-Listen 6053 120) { Ok 'ha-windows is listening on 6053' } else { Fail 'ha-windows is not listening on 6053 after 120 s' }
if (Wait-Listen $Port 30) { Ok "Event stream listening on 127.0.0.1:$Port" } else { Fail "Nothing is listening on 127.0.0.1:$Port. Check $HawLog" }

try {
    $client = New-Object Net.Sockets.TcpClient
    $client.Connect('127.0.0.1', $Port)
    $client.ReceiveTimeout = 5000
    $reader = New-Object IO.StreamReader($client.GetStream(), $Utf8NoBom)
    $hello = $reader.ReadLine()
    $client.Close()
    Ok "Stream says: $hello"
} catch {
    Fail "Could not read from the event stream: $($_.Exception.Message)"
}

Stop-Overlay
$ovLogStart = 0
if (Test-Path -LiteralPath $OvLog) { $ovLogStart = (Get-Item -LiteralPath $OvLog).Length }
Start-Process -FilePath $OvLnk
$connected = $false
for ($i = 0; $i -lt 120 -and -not $connected; $i++) {   # first start compiles a little C#, allow up to a minute
    Start-Sleep -Milliseconds 500
    if (Test-Path -LiteralPath $OvLog) {
        $fs = [IO.File]::Open($OvLog, 'Open', 'Read', 'ReadWrite')
        try { [void]$fs.Seek($ovLogStart, 'Begin'); $new = (New-Object IO.StreamReader($fs)).ReadToEnd() } finally { $fs.Dispose() }
        if ($new -match 'Connected to') { $connected = $true; Ok ("Overlay: " + (($new -split "`r?`n") | Where-Object { $_ -match 'Connected to' } | Select-Object -Last 1)) }
        elseif ($new -match 'Tick error|Bad event') { Warn "Overlay log: $new" }
    }
}
if (-not $connected) {
    $running = @(Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe'" | Where-Object { $_.CommandLine -like '*jarvis-overlay.ps1*' })
    if ($running.Count -gt 0) { Warn "The overlay is running but hasn't logged a connection yet. Check $OvLog" }
    else { Fail "The overlay did not start. Try it directly: powershell -NoProfile -ExecutionPolicy Bypass -File `"$OvScript`"" }
}

$logText = ''
if (Test-Path -LiteralPath $HawLog) {
    $fs = [IO.File]::Open($HawLog, 'Open', 'Read', 'ReadWrite')
    try { [void]$fs.Seek($logStart, 'Begin'); $logText = (New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8)).ReadToEnd() } finally { $fs.Dispose() }
}
$errs = @($logText -split "`r?`n" | Where-Object { $_ -match ' - (ERROR|CRITICAL) - ' -and $_ -notmatch '(?i)mdns|zeroconf|5353' })
if ($errs.Count -gt 0) { Warn ("{0} ERROR line(s) in the ha-windows log:" -f $errs.Count); $errs | Select-Object -First 10 | ForEach-Object { Info $_ } }
else { Ok 'No errors in the ha-windows log' }

if ($Demo) {
    Info 'Playing the demo exchange...'
    Start-Process -FilePath $ps -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', "`"$OvScript`"", '-Demo')
}

Write-Host ''
Write-Host 'Done. Say "Jarvis" to try it.' -ForegroundColor Cyan
Write-Host "Preview the look any time:  powershell -NoProfile -ExecutionPolicy Bypass -File `"$OvScript`" -Demo"
Write-Host "Undo everything:            powershell -NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Uninstall"
